// Extract items from input
const input = $input.first().json;
const items = input.body?.items || input.items || [];
const batchSize = input.body?.batchSize || input.batchSize || 10;

if (!Array.isArray(items) || items.length === 0) {
  throw new Error('No items provided. Expected { items: [...] }');
}

// Store batch config in workflow static data
$workflow.staticData.totalItems = items.length;
$workflow.staticData.batchSize = batchSize;
$workflow.staticData.startTime = Date.now();
$workflow.staticData.failedItems = [];

return items.map((item, index) => ({
  json: {
    ...item,
    _batchIndex: index,
    _batchTotal: items.length
  }
}));

// Process each item in the batch
// This is where your actual processing logic goes
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    // Simulate processing (replace with your actual logic)
    const processed = {
      ...item.json,
      processed: true,
      processedAt: new Date().toISOString(),
      status: 'success'
    };
    results.push({ json: processed });
  } catch (error) {
    // Track failed items for retry
    $workflow.staticData.failedItems.push({
      item: item.json,
      error: error.message
    });
    results.push({
      json: {
        ...item.json,
        processed: false,
        status: 'failed',
        error: error.message
      }
    });
  }
}

return results;

// Compile final results
const allItems = $input.all();
const staticData = $workflow.staticData;

const successful = allItems.filter(i => i.json.status === 'success');
const failed = allItems.filter(i => i.json.status === 'failed');

const summary = {
  totalItems: staticData.totalItems || allItems.length,
  processed: allItems.length,
  successful: successful.length,
  failed: failed.length,
  successRate: ((successful.length / allItems.length) * 100).toFixed(2) + '%',
  processingTime: Date.now() - (staticData.startTime || Date.now()) + 'ms',
  failedItems: failed.map(i => ({
    index: i.json._batchIndex,
    error: i.json.error
  }))
};

// Clear static data
delete $workflow.staticData.totalItems;
delete $workflow.staticData.batchSize;
delete $workflow.staticData.startTime;
delete $workflow.staticData.failedItems;

return [{
  json: {
    summary,
    results: allItems.map(i => i.json)
  }
}];
